Triangle $PAB$ is formed by three tangents to circle $O$ and $\angle APB = 40^\circ$.  Find $\angle AOB$.

[asy]
import graph;

unitsize(1.5 cm);

pair A, B, O, P, R, S, T;

R = dir(115);
S = dir(230);
T = dir(270);
P = extension(R, R + rotate(90)*(R), T, T + rotate(90)*(T));
A = extension(S, S + rotate(90)*(S), T, T + rotate(90)*(T));
B = extension(R, R + rotate(90)*(R), S, S + rotate(90)*(S));

draw(Circle((0,0),1));
draw((R + 0.1*(R - P))--P--(T + 0.1*(T - P)));
draw(A--B--O--cycle);

label("$A$", A, dir(270));
label("$B$", B, NW);
label("$O$", O, NE);
label("$P$", P, SW);
label("$R$", R, NW);
//label("$S$", S, NE);
label("$T$", T, dir(270));
[/asy]

Let $\mathbf{a} = \begin{pmatrix} 7 \\ -4 \\ -4 \end{pmatrix}$ and $\mathbf{c} = \begin{pmatrix} -2 \\ -1 \\ 2 \end{pmatrix}.$  Find the vector $\mathbf{b}$ such that $\mathbf{a},$ $\mathbf{b},$ and $\mathbf{c}$ are collinear, and $\mathbf{b}$ bisects the angle between $\mathbf{a}$ and $\mathbf{c}.$

[asy]
unitsize(0.5 cm);

pair A, B, C, O;

A = (-2,5);
B = (1,3);
O = (0,0);
C = extension(O, reflect(O,B)*(A), A, B);

draw(O--A,Arrow(6));
draw(O--B,Arrow(6));
draw(O--C,Arrow(6));
draw(interp(A,C,-0.1)--interp(A,C,1.1),dashed);

label("$\mathbf{a}$", A, NE);
label("$\mathbf{b}$", B, NE);
label("$\mathbf{c}$", C, NE);
[/asy]

